index 000000000000..4fafbbdc9255
--- /dev/null
+++ b/reproduce_issue.c
@@ -0,0 +1,96 @@
+#define _GNU_SOURCE
+#include <arpa/inet.h>
+#include <errno.h>
+#include <fcntl.h>
+#include <netinet/in.h>
+#include <netinet/tcp.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <sys/mman.h>
+#include <sys/socket.h>
+#include <sys/syscall.h>
+#include <sys/types.h>
+#include <unistd.h>
+#include <linux/tls.h>
+
+#ifndef TCP_ULP
+#define TCP_ULP 31
+#endif
+#ifndef TCP_TX_DELAY
+#define TCP_TX_DELAY 37
+#endif
+#ifndef SOL_TLS
+#define SOL_TLS 282
+#endif
+
+// Based on syzbot reproducer
+int main(void) {
+    int r0;
+    
+    r0 = socket(AF_INET6, SOCK_STREAM, 0); // r0 = socket$inet6_tcp(0xa, 0x1, 0x0)
+    if (r0 == -1) {
+        perror("socket");
+        return 1;
+    }
+
+    int optval_1 = 0x100000001;
+    setsockopt(r0, IPPROTO_TCP, TCP_TX_DELAY, &optval_1, 4); // setsockopt$inet6_tcp_int(r0, 0x6, 0x13, &(0x7f0000000000)=0x100000001, 0x4)
+
+    struct sockaddr_in6 addr = {
+        .sin6_family = AF_INET6,
+        .sin6_port = 0,
+        .sin6_addr = in6addr_loopback
+    };
+    if (connect(r0, (struct sockaddr*)&addr, sizeof(addr)) == -1) { // connect$inet6(r0, ...)
+        perror("connect");
+    }
+
+    if (setsockopt(r0, IPPROTO_TCP, TCP_ULP, "tls", 4) == -1) { // setsockopt$inet6_tcp_TCP_ULP(r0, 0x6, 0x1f, ...)
+        perror("setsockopt TCP_ULP");
+    }
+
+    int optval_repair = 1;
+    if (setsockopt(r0, IPPROTO_TCP, 20, &optval_repair, 4) == -1) { // setsockopt$inet6_tcp_TCP_REPAIR_QUEUE  (TCP_REPAIR_QUEUE=20)
+        perror("setsockopt TCP_REPAIR_QUEUE");
+    }
+
+    // TLS 1.2
+    struct tls12_crypto_info_aes_gcm_128 crypto;
+    memset(&crypto, 0, sizeof(crypto));
+    crypto.info.version = TLS_1_2_VERSION;
+    crypto.info.cipher_type = TLS_CIPHER_AES_GCM_128;
+    
+    // setsockopt$inet6_tcp_TLS_TX(r0, 0x11a, 0x1, ...)
+    if (setsockopt(r0, SOL_TLS, TLS_TX, &crypto, sizeof(crypto)) == -1) {
+        perror("setsockopt TLS_TX 1");
+    }
+    
+    // sendmsg$inet(r0, ...)
+    struct msghdr msg = {0};
+    struct iovec iov;
+    char buf[2] = {'n', '7'};
+    iov.iov_base = buf;
+    iov.iov_len = 2;
+    msg.msg_iov = &iov;
+    msg.msg_iovlen = 1;
+    sendmsg(r0, &msg, 0);
+
+    // setsockopt$inet6_tcp_TLS_TX(r0, 0x11a, 0x2, ...)
+    if (setsockopt(r0, SOL_TLS, TLS_TX, &crypto, sizeof(crypto)) == -1) {
+       perror("setsockopt TLS_TX 2");
+    }
+
+    // mmap ...
+
+    // connect$inet6(r0, ...)
+    if (connect(r0, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
+        perror("connect 2");
+    }
+
+    // recvfrom$inet6(r0, ...)
+    char recv_buf[0x1ff4];
+    recvfrom(r0, recv_buf, sizeof(recv_buf), 0x40, NULL, 0);
+
+    return 0;
+}

